import { FilterConfig } from '../types';

export const currencyFilterConfig: FilterConfig = {
  key: 'currency',
  order: 51,
  isCommon: true,
  calculator: (filterData) => filterData.currency?.default?.value ?? null,
  validator: (filterData, value) => {
    const options = filterData.currency?.values || [];
    return options.some((opt) => opt.value === value);
  },
  dependencies: [],
  metadata: {
    displayName: 'Currency',
    description: 'Currency filter',
  },
};
